    "longReadings": [
      {
        "title": "Reducing visual-manual demand in cockpit tasks",
        "source": {
          "name": "Original practice text",
          "url": ""
        },
        "text": "In an intelligent cockpit, every screen task has a visual-manual demand. The driver must look, understand, decide, and often tap a control while the vehicle is still moving. A useful HMI does not ask for the same level of effort in every situation. When traffic is light and the road is straight, a short climate adjustment or media choice may be acceptable. When the driver is turning, merging, or following dense navigation guidance, the system should reduce options, postpone nonessential prompting, or move the task to voice. Designers can lower demand by using larger touch targets, clear labels, and quick actions for frequent tasks. They can also use progressive disclosure, so secondary settings stay hidden until the vehicle is stopped or the driver clearly asks for them. Context-sensitive timing is critical because a simple card can become distracting at the wrong moment. The team should review glance duration, eyes-off-road time, and input errors during real driving scenarios, not only in a static prototype. Privacy-aware personalization can help decide which shortcut appears first, but it should explain why the shortcut is shown. Good cockpit task design balances speed, clarity, safety, and trust. It helps the driver complete useful actions without making the interface compete with the road.",
        "translation": "在智能座舱中，每一个屏幕任务都有视觉-手动负荷。驾驶员必须看、理解、决定，并且常常要在车辆仍在移动时点击控件。有用的 HMI 不会在所有情境下要求同样的努力程度。当交通较轻、道路笔直时，简短的空调调整或媒体选择可能可以接受。当驾驶员正在转弯、并线或跟随密集导航引导时，系统应减少选项、推迟非必要提示，或把任务转移到语音。设计师可以通过更大的触控目标、清晰标签和高频任务快捷入口来降低负荷。也可以使用渐进披露，让次要设置保持隐藏，直到车辆停止或驾驶员明确提出需求。情境敏感的时机很关键，因为一个简单卡片在错误时刻也会变得分心。团队应在真实驾驶场景中评审扫视时长、离路视线时间和输入错误，而不仅仅是在静态原型中评审。隐私感知的个性化可以帮助决定哪个快捷入口优先出现，但它应解释为什么显示该入口。好的座舱任务设计会平衡速度、清晰度、安全和信任。它帮助驾驶员完成有用操作，同时不让界面与道路争夺注意力。"
      }
    ],
