    "longReadings": [
      {
        "title": "Designing adaptive feedback for driver state",
        "source": {
          "name": "Original practice text",
          "url": ""
        },
        "text": "An intelligent cockpit should respond not only to vehicle events, but also to the driver's current state. If the driver is looking at the road, speaking a short command, and driving on a quiet highway, the system can use a light visual confirmation or a brief tone. If the driver is checking mirrors, entering a roundabout, or showing signs of fatigue, the same message may need to be delayed, simplified, or moved to an auditory channel. Driver state awareness is useful only when it leads to respectful feedback. The cockpit should not sound like it is blaming the driver, and it should not expose sensitive camera data without a clear reason. Instead, the HMI can explain the action in practical language: \"Traffic is complex, so I will show this reminder later.\" Designers should define an escalation ladder for attention and drowsiness alerts. A first signal may be a small icon, a repeated risk may trigger a tone, and a serious fatigue pattern may recommend a rest stop. The team also needs to manage false positives. If every glance away from the road becomes a warning, drivers will quickly ignore the system. Good adaptive feedback balances safety, privacy, timing, and trust.",
        "translation": "智能座舱不应只响应车辆事件，也应响应驾驶员的当前状态。如果驾驶员正在看路、发出简短语音指令，并且车辆行驶在安静高速路上，系统可以使用轻量视觉确认或简短提示音。如果驾驶员正在看后视镜、进入环岛或表现出疲劳迹象，同一条消息可能需要延后、简化，或转移到听觉通道。驾驶员状态感知只有在带来尊重用户的反馈时才有价值。座舱不应听起来像在责备驾驶员，也不应在没有明确理由的情况下暴露敏感摄像头数据。相反，HMI 可以用实用语言解释动作：\"交通情况复杂，所以我稍后再显示这条提醒。\" 设计师应为注意力和疲劳提醒定义升级阶梯。第一次信号可以是小图标，重复风险可以触发提示音，严重疲劳模式可以建议休息站。团队还需要管理误报。如果每一次视线离开道路都变成警告，驾驶员很快会忽略系统。好的自适应反馈会平衡安全、隐私、时机和信任。"
      }
    ],
